public class Main {
  public static String formatGreeting(String[] args) {
    if (args.length >= 2) {
      return args[0] + ", " + args[1] + "!";
    } else if (args.length == 1) {
      return "Hello, " + args[0] + "!";
    }
    return "Hello, World!";
  }

  public static void main(String[] args) {
    System.out.println(formatGreeting(new String[]{"Bonjour", "DAI"}));
    System.out.println(formatGreeting(new String[]{"Alice"}));
    System.out.println(formatGreeting(new String[]{}));
  }
}

