function resolveMavenPaths(groupId, artifactId, version) {
  const groupPath = groupId.replace(/\./g, '/');
  const jarName = `${artifactId}-${version}.jar`;
  return {
    m2Path: `~/.m2/repository/${groupPath}/${artifactId}/${version}/${jarName}`,
    targetJar: `target/${jarName}`
  };
}

const res = resolveMavenPaths('info.picocli', 'picocli', '4.7.7');
console.log(res.m2Path);
console.log(res.targetJar);

