DEFAULT_PHASES = ["validate", "compile", "test", "package", "verify", "install", "deploy"]

def resolve_maven_command(args):
    executed = []
    for arg in args:
        if arg == "clean":
            executed.append("clean")
        elif arg in DEFAULT_PHASES:
            idx = DEFAULT_PHASES.index(arg)
            executed.extend(DEFAULT_PHASES[:idx + 1])
    return executed

print(resolve_maven_command(["clean", "package"]))
print(resolve_maven_command(["test"]))

